        {'id':'D01','priority':'P1','topic':'joint kinship and exact-age sampling','status':'open_not_repaired','parent_role_age_review_cases':3,'examples':d['examples']['parent_ego_age_gap_under12_reference_review'],'source_rule':'joint coarse motif -> separately drawn exact ages -> direction-only older/younger check','interpretation':'unexplained reference parent semantics; not proof of source invalidity or clinical/legal impossibility','required_change':'source relation/type review then joint age/role generation; retain unknowns and failures instead of invented special-family explanations'},
