        {'id':'D03','priority':'P1','topic':'independent service need vs operator availability','status':'open_not_repaired','service_instance_counts':d['service_need_counts'],'count_unit':'service records across two-date support in10000 pairs,not independent questionnaire count','required_change':'declare service/next-use objective and reason before solving A on resource calendar; audit demand and schedule separately','reference_deadlines_may_be_given_experimental_conditions':True,'does_not_establish_observed_individual_need':True},
        {'id':'D04','priority':'P2','topic':'auxiliary support and correlated synthetic demographics','status':'grouped_evaluation_sensitivity_pending_not_current_leakage_claim','single_source_selected_slots':d['counts']['selected_atom_single_source_slots'],'duplicates':d['duplicates'],'required_change':'report effective structural support; prespecify role and motif/near-profile grouped evaluation sensitivities; no10kIID claims'},
